record Item(Long productId, Integer quantity) {}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @PostMapping
    public OrderResponse createOrder(@RequestBody OrderRequest request) {
        // Jackson deserializes JSON to OrderRequest automatically
        var order = new Order(request.userId(), request.items());
        var savedOrder = orderService.save(order);
        // Jackson serializes OrderResponse to JSON automatically
        return new OrderResponse(savedOrder.id(), savedOrder.status());
    }
}

record OrderRequest(Long userId, List<String> items) {}

record OrderResponse(
    @JsonProperty("order_id") Long orderId, // Renames field in JSON
    String status
) {}

