@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService service;

    public OrderController(OrderService service) {
        this.service = service;
    }

    @PostMapping
    public OrderResponse create(@RequestBody CreateOrderRequest request) {
        // Deserialization (inbound): JSON request body -> CreateOrderRequest object
        var saved = service.create(request.userId(), request.items());
        // Serialization (outbound): OrderResponse object -> JSON response body
        return new OrderResponse(saved.id(), saved.status());
    }
}

record CreateOrderRequest(Long userId, List<String> items) {}  // JSON -> Java
record OrderResponse(Long id, String status) {}                // Java -> JSON
