// Entity: maps to a DB table, managed by JPA (persistence layer)
@Entity
public class Order {
    @Id @GeneratedValue
    private Long id;
    private String customerEmail;
    @OneToMany(mappedBy = "order")
    private List<OrderItem> items;   // lazy relation - risky to serialize directly
    // getters / setters
}

// DTO: plain record for the API layer (controlled, safe to serialize)
record OrderResponse(Long id, String customerEmail, int itemCount) {}

@RestController
@RequestMapping("/api/orders")
class OrderController {
    private final OrderRepository repo;
    OrderController(OrderRepository repo) { this.repo = repo; }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable Long id) {
        var order = repo.findById(id).orElseThrow();
        // Map Entity -> DTO so we never leak the JPA model or hit lazy-loading issues
        return new OrderResponse(order.getId(), order.getCustomerEmail(),
                                 order.getItems().size());
    }
}
